 sealed class ArchiveHandler(byte[] archive):System.Net.Http.HttpMessageHandler {protected override System.Threading.Tasks.Task<System.Net.Http.HttpResponseMessage> SendAsync(System.Net.Http.HttpRequestMessage request,System.Threading.CancellationToken cancellationToken)=>System.Threading.Tasks.Task.FromResult(new System.Net.Http.HttpResponseMessage(System.Net.HttpStatusCode.OK){Content=new System.Net.Http.ByteArrayContent(archive)});}
 public static int Run(Shell shell,AppFiles files){var results=new List<object>();int failed=0;
  void Test(string name,Action action){try{action();results.Add(new{Name=name,Passed=true});}catch(Exception ex){failed++;results.Add(new{Name=name,Passed=false,Error=ex.Message});}}
  void Check(bool value,string message){if(!value)throw new Exception(message);}
  Test("Mica visual comparison tolerates small tint changes but rejects black",()=>{using var baseline=new System.Drawing.Bitmap(210,80);using var normal=new System.Drawing.Bitmap(210,80);using var black=new System.Drawing.Bitmap(210,80);using(var g=System.Drawing.Graphics.FromImage(baseline))g.Clear(System.Drawing.Color.FromArgb(45,26,27));using(var g=System.Drawing.Graphics.FromImage(normal))g.Clear(System.Drawing.Color.FromArgb(34,31,31));using(var g=System.Drawing.Graphics.FromImage(black))g.Clear(System.Drawing.Color.Black);Check(Tests030.BackdropSimilar(baseline,normal)&&!Tests030.BackdropSimilar(baseline,black),"Tint tolerance or black-surface detection");});
  Test("Open Net release discovery filters channel assets and source",()=>{object Release(string version,bool pre,bool portable=false,string host="github.com"){string name="Open-Net-"+version.TrimStart('v')+"-Windows-x64"+(portable?"-Portable.zip":".exe");return new{draft=false,prerelease=pre,tag_name=version,html_url="https://github.com/MaratKraft/Open-Net/releases/tag/"+version,assets=new[]{new{name,browser_download_url="https://"+host+"/MaratKraft/Open-Net/releases/download/"+version+"/"+name,size=123}}};}string Data(params object[] items)=>JsonSerializer.Serialize(items);var stable=Release("v0.4.1",false);var alpha=Release("v0.5.0-alpha.1",true);Check(OpenNetReleaseCheck.Select(Data(stable,alpha),"0.4.0",false,false)?.Version=="v0.4.1","Stable channel");Check(OpenNetReleaseCheck.Select(Data(stable,alpha),"0.4.0",true,false)?.Version=="v0.5.0-alpha.1","Pre-release channel");Check(OpenNetReleaseCheck.Select(Data(stable),"0.4.2",true,false)==null,"Downgrade");try{OpenNetReleaseCheck.Select(Data(stable),"0.4.0",true,true);throw new Exception("Wrong package accepted");}catch(InvalidDataException){}Check(OpenNetReleaseCheck.Select(Data(Release("v0.4.1",false,true)),"0.4.0",false,true)!=null,"Portable package");try{OpenNetReleaseCheck.Select(Data(Release("v0.4.1",false,false,"example.com")),"0.4.0",false,false);throw new Exception("Untrusted source accepted");}catch(InvalidDataException){}});
  Test("Open Net update versions follow SemVer precedence",()=>{UpdateVersion Parse(string s){Check(UpdateVersion.TryParse(s,out var x),"Invalid valid version "+s);return x!;}var ordered=new[]{"1.0.0-alpha","1.0.0-alpha.1","1.0.0-alpha.beta","1.0.0-beta","1.0.0-beta.2","1.0.0-beta.11","1.0.0-rc.1","1.0.0"};for(int i=1;i<ordered.Length;i++)Check(Parse(ordered[i-1]).CompareTo(Parse(ordered[i]))<0,"Prerelease ordering");Check(Parse("v0.4.0-alpha.1+abc").CompareTo(Parse("0.4.0-alpha.1+def"))==0,"Metadata changed precedence");Check(Parse("0.4.0-alpha.1").CompareTo(Parse("0.3.3"))>0,"Older stable is not an upgrade");foreach(string invalid in new[]{"1.02.3","1.0.0-01","1.0","1.0.0+","1.0.0-","1.0.0-alpha..1"})Check(!UpdateVersion.TryParse(invalid,out _),"Invalid version accepted");});
  Test("Pre-release 1 version follows semantic version precedence",()=>{Check(UpdateVersion.TryParse("v0.4.0-pre.1",out var pre)&&UpdateVersion.TryParse("v0.4.0-alpha.1",out var alpha)&&UpdateVersion.TryParse("v0.4.0",out var stable)&&pre!.CompareTo(alpha)>0&&pre.CompareTo(stable)<0,"Unexpected pre-release version ordering");});
  Test("DNS icon in module editor uses the same filled geometry",()=>{var editor=new ModuleOrderEditor(shell.Window,new[]{"dns"});var panel=(StackPanel)((System.Windows.Documents.AdornerDecorator)editor.Content).Child;var row=(Border)panel.Children[0];var marker=((Grid)row.Child).Children.OfType<System.Windows.Shapes.Path>().Single();var source=((Grid)shell.Window.FindName("DnsGlyph")).Children.OfType<System.Windows.Shapes.Path>().Single();Check(marker.Fill!=null&&marker.Stroke==null&&marker.Data.Bounds==source.Data.Bounds,"Module editor DNS symbol differs from main icon");});
  Test("Zapret stop accepts saved strategy but rejects changed launch identity",()=>{var original=new OwnedReceipt(Guid.NewGuid().ToString("N"),42,123,"C:\\fixture\\winws.exe","zapret");var saved=original with{Profile="general (ALT13).bat"};Check(ElevatedActions.SameLaunch(original,saved),"Saved strategy blocked own launch");Check(!ElevatedActions.SameLaunch(original,saved with{Pid=43})&&!ElevatedActions.SameLaunch(original,saved with{StartFileTime=124})&&!ElevatedActions.SameLaunch(original,saved with{Executable="C:\\other\\winws.exe"})&&!ElevatedActions.SameLaunch(original,saved with{Token=Guid.NewGuid().ToString("N")})&&!ElevatedActions.SameLaunch(original,saved with{Module="tg"})&&!ElevatedActions.SameLaunch(null,saved),"Changed launch identity accepted");});
  Test("external selection refuses ambiguous, changed, inaccessible and service processes",()=>{string path=Path.GetFullPath(Path.Combine(files.Root,"winws.exe"));long time=DateTime.UtcNow.ToFileTimeUtc();var observed=new NetworkHub.Core.ProcessObservation(123,path,DateTime.FromFileTimeUtc(time),true);var identity=new Probe(true,true,time,path);OwnedReceipt Select(NetworkHub.Core.ProcessObservation[] list,Probe p,bool service=false)=>ExternalProcessControl.Select("zapret",path,list,_=>p,_=>service);Check(Select(new[]{observed},identity).Pid==123,"Valid identity rejected");void Reject(Action action){bool rejected=false;try{action();}catch(InvalidOperationException){rejected=true;}Check(rejected,"Unsafe target accepted");}Reject(()=>Select(Array.Empty<NetworkHub.Core.ProcessObservation>(),identity));Reject(()=>Select(new[]{observed,observed with{Pid=124}},identity));Reject(()=>Select(new[]{observed},identity with{StartFileTime=time+1}));Reject(()=>Select(new[]{observed},identity with{Executable=path+".other"}));Reject(()=>Select(new[]{observed with{MetadataAccessible=false}},identity));Reject(()=>Select(new[]{observed},identity,true));});
  Test("external process binary allowlist rejects unreviewed executables",()=>{Check(ExternalProcessControl.ReviewedBinary("zapret","AFFB4F69D2EA302A7ABCCD5325D81826E140DDAE014F1E070BC4A6C0DD555188"),"Known Zapret not reviewed");Check(!ExternalProcessControl.ReviewedBinary("zapret",new string('0',64))&&!ExternalProcessControl.ReviewedBinary("tg",new string('0',64))&&!ExternalProcessControl.ReviewedBinary("other",new string('0',64)),"Unknown binary allowed");});
  Test("exact stop is tested only on a separately created own stub",()=>{string host=Environment.ProcessPath!;using var supervisor=new NetworkHub.Core.StubSupervisor(host,host,NetworkHub.Core.Metadata.Hash(host),Path.Combine(files.Data,"external-stop-stub-"+Guid.NewGuid().ToString("N")),true);var stub=supervisor.Start();var p=ProcessIdentity.Read(stub.Pid);Check(p.Exists&&p.IdentityReadable&&p.Executable!=null,"Stub identity unavailable");var receipt=new OwnedReceipt(Guid.NewGuid().ToString("N"),stub.Pid,p.StartFileTime,p.Executable!,"tg");bool rejected=false;try{OwnedStop.Stop(receipt with{StartFileTime=receipt.StartFileTime+1},false,true);}catch(InvalidOperationException){rejected=true;}Check(rejected&&ProcessIdentity.Read(stub.Pid).Exists,"Changed identity was stopped");OwnedStop.Stop(receipt,false,true);Check(!ProcessIdentity.Read(stub.Pid).Exists,"Exact own stub did not exit");});
  Test("hosts inspection detects only active exact domains and aliases",()=>{var found=HostsInspection.Parse(new[]{"# 1.2.3.4 chatgpt.com","1.2.3.4 CHATGPT.COM auth.openai.com # note","::1 gemini.google.com.","bad gemini.google.com","1.1.1.1 fakechatgpt.com"});Check(found.Length==3&&found.Contains("CHATGPT.COM")&&found.Contains("auth.openai.com")&&found.Contains("gemini.google.com"),"Host parsing or domain boundary");});
  Test("TG official digest verification accepts future versions and rejects modified files",()=>{string version="v9.8.7",hash=new string('A',64);string Json(string host,string digest)=>JsonSerializer.Serialize(new{draft=false,tag_name=version,assets=new[]{new{name="TgWsProxy_windows.exe",browser_download_url="https://"+host+"/Flowseal/tg-ws-proxy/releases/download/"+version+"/TgWsProxy_windows.exe",digest="sha256:"+digest}}});TgRuntimeControl.ValidateRelease(Json("github.com",hash),version,hash);foreach(string input in new[]{Json("example.com",hash),Json("github.com",new string('B',64))}){bool rejected=false;try{TgRuntimeControl.ValidateRelease(input,version,hash);}catch(InvalidDataException){rejected=true;}Check(rejected,"Untrusted TG accepted");}});
  Test("verified own stub tree stops fully and restarts without touching independent stub",()=>{string host=Environment.ProcessPath!;using var supervisor=new NetworkHub.Core.StubSupervisor(host,host,NetworkHub.Core.Metadata.Hash(host),Path.Combine(files.Data,"tree-lifecycle-"+Guid.NewGuid().ToString("N")),true);var independent=supervisor.Start();for(int run=0;run<2;run++){var started=supervisor.Start(child:true);var timer=System.Diagnostics.Stopwatch.StartNew();while(supervisor.Tree(started.Token).Length<2&&timer.ElapsedMilliseconds<5000)System.Threading.Thread.Sleep(25);Check(supervisor.Tree(started.Token).Length==2,"Child did not start");OwnedReceipt[] Snapshot()=>supervisor.Tree(started.Token).Select(pid=>{var p=ProcessIdentity.Read(pid);return new OwnedReceipt(started.Token.ToString("N"),pid,p.StartFileTime,p.Executable!,"tg");}).ToArray();var members=Snapshot();var root=members.Single(p=>p.Pid==started.Pid);bool rejected=false;try{OwnedStop.Stop(root,true,true,Array.Empty<OwnedReceipt>(),Snapshot);}catch(InvalidOperationException){rejected=true;}Check(rejected&&ProcessIdentity.Read(root.Pid).Exists,"Changed tree was stopped");OwnedStop.Stop(root,true,true,members,Snapshot);Check(members.All(p=>!ProcessIdentity.Read(p.Pid).Exists)&&ProcessIdentity.Read(independent.Pid).Exists,"Tree did not exit or independent process stopped");}});
  Test("writable stale receipt alone cannot claim a process after shell restart",()=>{var isolated=new AppFiles(Path.Combine(files.Root,"test-results/reattach-"+Guid.NewGuid().ToString("N")));var identity=ProcessIdentity.Read(Environment.ProcessId);Check(identity.Exists&&identity.IdentityReadable&&identity.Executable!=null,"Fixture process identity unavailable");var receipt=new OwnedReceipt(Guid.NewGuid().ToString("N"),Environment.ProcessId,identity.StartFileTime,identity.Executable!,"zapret");var dir=Path.Combine(isolated.Data,"owned");Directory.CreateDirectory(dir);File.WriteAllText(Path.Combine(dir,"zapret.json"),JsonSerializer.Serialize(receipt));var observed=new NetworkHub.Core.ProcessObservation(receipt.Pid,receipt.Executable,DateTime.FromFileTimeUtc(receipt.StartFileTime),true);var runtime=new ToolRuntime(isolated,false){ProcessListForTests=_=>new[]{observed}};Check(runtime.Observe("zapret",new UserSettings()).State==ObservedState.External,"Untrusted file claimed own process");Check(ProcessIdentity.ObserveOwned(receipt with{StartFileTime=receipt.StartFileTime+1}).State==ObservedState.Stopped,"Changed identity accepted");});
  ThemeManager.SystemDarkForTests=()=>true;
  Test("new System and legacy dark configuration",()=>{var isolated=new AppFiles(Path.Combine(files.Root,"test-results/legacy"));Check(isolated.Defaults().Theme=="system","New default");Directory.CreateDirectory(Path.GetDirectoryName(isolated.SettingsPath)!);File.WriteAllText(isolated.SettingsPath,"{\"Language\":\"ru\",\"Strategy\":\"general (ALT2).bat\",\"ConfirmStartStop\":false}");var old=isolated.Load();Check(old.Theme=="dark"&&old.Language=="ru"&&!old.ConfirmStartStop&&old.Strategy=="general (ALT2).bat","Legacy settings preserved");old.Theme="light";isolated.Save(old);Check(isolated.Load().Theme=="light","Persisted theme");});
  Test("first run uses Windows UI language, saved choice survives culture changes",()=>{foreach(var name in new[]{"ru-RU","ru-KZ"})Check(AppFiles.FirstRunLanguage(System.Globalization.CultureInfo.GetCultureInfo(name))=="ru","Russian UI language");foreach(var name in new[]{"en-US","de-DE","fr-FR","uk-UA","kk-KZ"})Check(AppFiles.FirstRunLanguage(System.Globalization.CultureInfo.GetCultureInfo(name))=="en","English fallback");var isolated=new AppFiles(Path.Combine(files.Root,"test-results/lang-"+Guid.NewGuid().ToString("N")));var before=System.Globalization.CultureInfo.CurrentUICulture;try{System.Globalization.CultureInfo.CurrentUICulture=System.Globalization.CultureInfo.GetCultureInfo("ru-RU");Check(isolated.Load().Language=="ru","Fresh Russian UI");var saved=isolated.Load();saved.Language="en";isolated.Save(saved);System.Globalization.CultureInfo.CurrentUICulture=System.Globalization.CultureInfo.GetCultureInfo("ru-KZ");Check(isolated.Load().Language=="en","Saved preference overwritten");}finally{System.Globalization.CultureInfo.CurrentUICulture=before;}});
  var zapretFixture=Environment.GetEnvironmentVariable("OPENNET_ZAPRET_FIXTURE");
  if(!string.IsNullOrWhiteSpace(zapretFixture))Test("official 1.10.4 strategies pass verified manifest and parser",()=>{var trusted=ModuleTrust.HashPayload(zapretFixture);foreach(string name in new[]{"general.bat",StrategyList.Preferred}){string path=Path.Combine(zapretFixture,name);try{_=NetworkHub.Adapters.ReviewedStrategy.Extract(File.ReadAllText(path),zapretFixture,Path.Combine(files.Data,"fixture-lists"));}catch(Exception ex){throw new Exception(name+": "+ex.Message,ex);}Check(NetworkHub.Adapters.ReviewedStrategy.Supported(zapretFixture,name,trusted),"Official trusted strategy rejected: "+name);var wrong=new System.Collections.Generic.Dictionary<string,string>(trusted,StringComparer.OrdinalIgnoreCase){[name]=new string('0',64)};Check(!NetworkHub.Adapters.ReviewedStrategy.Supported(zapretFixture,name,wrong),"Mismatched manifest bypassed by built-in hash");}});
  var archiveFixture=Environment.GetEnvironmentVariable("OPENNET_ZAPRET_ARCHIVES");
  if(!string.IsNullOrWhiteSpace(archiveFixture))Test("isolated official 1.10.3 install and 1.10.4 update retain selected ALT13",()=>{var isolated=new AppFiles(Path.Combine(files.Root,"test-results/zapret-upgrade-"+Guid.NewGuid().ToString("N")));var settings=isolated.Defaults();foreach(string version in new[]{"1.10.3","1.10.4"}){byte[] archive=File.ReadAllBytes(Path.Combine(archiveFixture,"zapret-"+version+".zip"));string name="zapret-discord-youtube-"+version+".zip",url="https://github.com/Flowseal/zapret-discord-youtube/releases/download/"+version+"/"+name;var asset=new ReleaseAsset("zapret",version,name,url,archive.Length,"sha256:"+Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(archive)),"https://github.com/Flowseal/zapret-discord-youtube/releases/tag/"+version,version);using var installer=new ModuleInstaller(isolated,new ArchiveHandler(archive),_=>false);System.Threading.Tasks.Task.Run(()=>installer.Install(asset)).GetAwaiter().GetResult();settings=installer.ApplyManaged(settings);Check(settings.Strategy==StrategyList.Preferred,"Preferred strategy changed");Check(NetworkHub.Adapters.ReviewedStrategy.Supported(settings.ZapretDirectory,settings.Strategy,ModuleTrust.ZapretHashes(isolated,settings.ZapretDirectory)),"Installed strategy not trusted");Check(installer.Current("zapret")?.Version==version,"Incorrect manifest version");}});
  Test("Legacy settings are backed up before conversion",()=>{var isolated=new AppFiles(Path.Combine(files.Root,"test-results/legacy-backup-"+Guid.NewGuid().ToString("N")));Directory.CreateDirectory(Path.GetDirectoryName(isolated.SettingsPath)!);byte[] original=System.Text.Encoding.UTF8.GetBytes("{\"Language\":\"ru\",\"Strategy\":\"general (ALT2).bat\"}");File.WriteAllBytes(isolated.SettingsPath,original);var settings=isolated.Load();isolated.Save(settings);string backup=Directory.GetFiles(Path.Combine(isolated.Data,"Backups","Settings"),"v0.3.3-*.json").Single();Check(original.SequenceEqual(File.ReadAllBytes(backup))&&isolated.Load().Strategy==settings.Strategy,"Original backup or settings lost");isolated.Save(settings);Check(Directory.GetFiles(Path.GetDirectoryName(backup)!,"*.json").Length==1,"Unexpected repeated backup");});
  var legacyFixture=Environment.GetEnvironmentVariable("OPENNET_033_FIXTURE");
  if(!string.IsNullOrWhiteSpace(legacyFixture))Test("Copied v0.3.3 configuration and managed module manifests survive conversion",()=>{string root=Path.Combine(files.Root,"test-results","copied-033-"+Guid.NewGuid().ToString("N"));string data=Path.Combine(root,"Data");SelfTests.CopyTree(legacyFixture,data);string oldModules=Path.Combine(data,"Modules");if(Directory.Exists(oldModules))Directory.Move(oldModules,Path.Combine(root,"Modules"));var copy=new AppFiles(root,data);byte[] before=File.ReadAllBytes(copy.SettingsPath);var settings=copy.Load();using var installer=new ModuleInstaller(copy,runningProbe:_=>false);foreach(string id in new[]{"zapret","tg"})if(File.Exists(installer.Manifest(id)))Check(installer.Current(id)!=null,"Copied module manifest unusable: "+id);copy.Save(settings);Check(before.SequenceEqual(File.ReadAllBytes(Directory.GetFiles(Path.Combine(data,"Backups","Settings"),"v0.3.3-*.json").Single())),"Legacy backup differs");Check(copy.Load().Strategy==settings.Strategy&&copy.Load().Language==settings.Language,"Legacy preferences changed");});
  Test("system resolver and manual precedence",()=>{Check(ThemeManager.Resolve("system",false)=="light"&&ThemeManager.Resolve("system",true)=="dark"&&ThemeManager.Resolve("dark",false)=="dark"&&ThemeManager.Resolve("light",true)=="light","Theme policy");});
  Test("live palette resources in both themes",()=>{foreach(string mode in new[]{"dark","light"}){ThemeManager.SetMode(mode);var text=((SolidColorBrush)ThemeManager.Brush("Text")).Color;var surface=((SolidColorBrush)ThemeManager.Brush("Surface")).Color;Check(mode=="dark"?text.R>surface.R+150:surface.R>text.R+150,"Text contrast");Check(((SolidColorBrush)shell.Window.Foreground).Color==text,"Main resource update");}});
  Test("System updates without modifying Windows settings",()=>{ThemeManager.SetMode("system");ThemeManager.SystemDarkForTests=()=>false;ThemeManager.Refresh();Check(!ThemeManager.IsDark,"System light");ThemeManager.SystemDarkForTests=()=>true;ThemeManager.Refresh();Check(ThemeManager.IsDark,"System dark");});
  Test("empty folder and invalid EXE are not installed modules",()=>{var root=Path.Combine(files.Root,"test-results/readiness");var isolated=new AppFiles(root);string empty=Path.Combine(root,"empty");Directory.CreateDirectory(empty);string invalid=Path.Combine(root,"invalid.exe");File.WriteAllText(invalid,"test data, never executed");var readiness=new ModuleReadiness(isolated);var settings=new UserSettings{ZapretDirectory=empty,TgExe=invalid};Check(!readiness.Read("zapret",settings).Installed&&!readiness.Read("tg",settings).Installed,"No folder-only readiness");});
  Test("download and refresh geometry/localization",()=>{Check(ModuleActionPresentation.Glyph(false)!=ModuleActionPresentation.Glyph(true),"Separate glyphs");Geometry.Parse(ModuleActionPresentation.Download);Geometry.Parse(ModuleActionPresentation.Refresh);foreach(string language in new[]{"en","ru"}){L.Set(language);Check(ModuleActionPresentation.Caption(false)==L.T("Install")&&ModuleActionPresentation.Caption(true)==L.T("Check for updates"),"Action localization");}L.Set("en");});
  Test("compact layout and isolated scrolling",()=>{var surface=(FrameworkElement)shell.Window.Content;surface.Measure(new Size(460,710));surface.Arrange(new Rect(0,0,460,710));surface.UpdateLayout();var list=shell.Find<StackPanel>("ModuleList");Check(list.Children.Count==3,"Three independent modules");foreach(string name in new[]{"ZapretRow","TgRow"})Check(shell.Find<Border>(name).ActualHeight<=80,"Compact row");Check(shell.Find<ScrollViewer>("MainScroll").Content==list,"Only module list scrolls");Check(shell.Find<TextBlock>("ZapretStrategy").TextTrimming==TextTrimming.CharacterEllipsis,"Long strategies trim with tooltip");});
  Test("icon actions are separate and keyboard accessible",()=>{foreach(string module in new[]{"Zapret","Tg"}){var install=shell.Find<Button>(module+"Install");var gear=shell.Find<Button>(module+"Settings");Check(install.Width>=28&&gear.Width>=28&&install.Focusable&&gear.Focusable&&install!=gear,"Independent actions");}FocusCues.SetMode(true);Check(shell.Find<Button>("Settings").FocusVisualStyle!=null,"Keyboard focus");FocusCues.SetMode(false);Check(shell.Find<Button>("Settings").FocusVisualStyle==null,"Mouse cue absent");});
